import time
import numpy as np
from scipy.optimize import linprog

N = 26
PI, PJ = np.triu_indices(N, 1)
M = len(PI)
MARGIN = 1e-9


def _valid(P):
    if P.shape != (N, 3) or not np.all(np.isfinite(P)):
        return False
    x, y, r = P[:, 0], P[:, 1], P[:, 2]
    if np.any(r < 0):
        return False
    if np.any(x - r < -1e-12) or np.any(x + r > 1 + 1e-12):
        return False
    if np.any(y - r < -1e-12) or np.any(y + r > 1 + 1e-12):
        return False
    d = np.hypot(x[PI] - x[PJ], y[PI] - y[PJ])
    return bool(np.all(d >= r[PI] + r[PJ] - 1e-12))


def _radii(C):
    # For fixed centers, the best radii are an LP: maximize sum r
    # subject to r_i + r_j <= d_ij and r_i <= distance to walls.
    x, y = C[:, 0], C[:, 1]
    bound = np.minimum(np.minimum(x, 1 - x), np.minimum(y, 1 - y))
    if np.any(bound < 0):
        return None
    d = np.hypot(x[PI] - x[PJ], y[PI] - y[PJ])
    A = np.zeros((M, N))
    A[np.arange(M), PI] = 1
    A[np.arange(M), PJ] = 1
    res = linprog(-np.ones(N), A_ub=A, b_ub=d,
                  bounds=list(zip(np.zeros(N), bound)), method="highs")
    if res.status != 0:
        return None
    r = np.minimum(np.maximum(res.x - MARGIN, 0), bound)
    # Repair tiny HiGHS tolerance violations so the exact check passes.
    for _ in range(20):
        v = r[PI] + r[PJ] - d
        bad = v > 0
        if not bad.any():
            break
        delta = np.zeros(N)
        np.add.at(delta, PI[bad], v[bad] / 2 + 1e-12)
        np.add.at(delta, PJ[bad], v[bad] / 2 + 1e-12)
        r = np.maximum(r - delta, 0)
    return np.column_stack([x, y, r])


def _grid():
    k = int(np.ceil(np.sqrt(N)))
    pts = [((i + .5) / k, (j + .5) / k) for i in range(k) for j in range(k)][:N]
    return np.array([(x, y, .5 / k) for x, y in pts])


def solve(time_limit, best_so_far):
    t0 = time.time()
    budget = min(0.4 * time_limit, 7.0)
    rng = np.random.default_rng(2024)

    best, best_score = None, -1.0
    if best_so_far is not None:
        B = np.asarray(best_so_far, float)
        if _valid(B):
            best, best_score = B, B[:, 2].sum()

    def consider(P):
        nonlocal best, best_score
        if P is not None and _valid(P) and P[:, 2].sum() > best_score + 1e-12:
            best, best_score = P, P[:, 2].sum()

    # Seed the walk with a few random center configurations.
    cur = best
    for _ in range(4):
        P = _radii(rng.uniform(0.05, 0.95, (N, 2)))
        consider(P)
        if P is not None and (cur is None or P[:, 2].sum() > cur[:, 2].sum()):
            cur = P

    if cur is None:
        return best if best is not None else _grid()

    # Simulated annealing over centers; radii are solved exactly by LP.
    T0, T1 = 0.02, 0.0005
    it, last_gain = 0, 0
    while True:
        el = time.time() - t0
        if el >= budget:
            break
        T = T0 * (T1 / T0) ** (el / budget)
        it += 1

        C = cur[:, :2].copy()
        u = rng.random()
        if u < 0.4:
            C[rng.integers(N)] = rng.uniform(0.05, 0.95, 2)
        elif u < 0.8:
            C[rng.integers(N)] += rng.normal(0, 0.08, 2)
        else:
            C += rng.normal(0, 0.015, (N, 2))
        C = np.clip(C, 0, 1)

        P = _radii(C)
        if P is None:
            continue
        s, cs = P[:, 2].sum(), cur[:, 2].sum()
        if s >= cs or rng.random() < np.exp((s - cs) / T):
            cur = P

        if s > best_score + 1e-12:
            consider(P)
            last_gain = it

        # Restart from the incumbent after a long stall.
        if it - last_gain > 400:
            cur = best
            last_gain = it

    return best if best is not None else _grid()

import time
import numpy as np
from scipy.optimize import linprog, minimize

N = 26
PI, PJ = np.triu_indices(N, 1)
M = len(PI)
A_PAIR = np.zeros((M, N))
A_PAIR[np.arange(M), PI] = 1
A_PAIR[np.arange(M), PJ] = 1


def _valid(P):
    if not isinstance(P, np.ndarray) or P.shape != (N, 3) or not np.all(np.isfinite(P)):
        return False
    x, y, r = P[:, 0], P[:, 1], P[:, 2]
    if np.any(r < 0):
        return False
    if np.any(x - r < -1e-12) or np.any(x + r > 1 + 1e-12):
        return False
    if np.any(y - r < -1e-12) or np.any(y + r > 1 + 1e-12):
        return False
    d = np.hypot(x[PI] - x[PJ], y[PI] - y[PJ])
    return bool(np.all(d >= r[PI] + r[PJ] - 1e-12))


def _repair(C, r):
    # Shrink radii until every constraint holds with a small safety margin.
    C = np.clip(np.asarray(C, float), 0, 1)
    x, y = C[:, 0], C[:, 1]
    r = np.asarray(r, float).copy()
    bound = np.minimum(np.minimum(x, 1 - x), np.minimum(y, 1 - y))
    r = np.clip(np.minimum(r, bound), 0, None)
    d = np.hypot(x[PI] - x[PJ], y[PI] - y[PJ])
    for _ in range(200):
        bad = np.where(r[PI] + r[PJ] > d * (1 - 1e-12))[0]
        if bad.size == 0:
            break
        for k in bad:
            i, j = PI[k], PJ[k]
            si = r[i] + r[j]
            if si > 0:
                f = min(1.0, d[k] * (1 - 1e-11) / si)
                r[i] *= f
                r[j] *= f
    return np.column_stack([x, y, r])


def _lp_radii(C):
    # Fixed centers: the best radii are an LP (maximize sum r).
    C = np.clip(np.asarray(C, float), 0, 1)
    x, y = C[:, 0], C[:, 1]
    bound = np.minimum(np.minimum(x, 1 - x), np.minimum(y, 1 - y))
    d = np.hypot(x[PI] - x[PJ], y[PI] - y[PJ])
    try:
        res = linprog(-np.ones(N), A_ub=A_PAIR, b_ub=d,
                      bounds=list(zip(np.zeros(N), bound)), method="highs")
    except Exception:
        return None
    if res.status != 0:
        return None
    return _repair(C, res.x - 1e-9)


def _slsqp(P0):
    # Joint polish of centers and radii with analytic jacobians.
    def cons(z):
        x, y, r = z[:N], z[N:2 * N], z[2 * N:]
        dx = x[PI] - x[PJ]
        dy = y[PI] - y[PJ]
        s = r[PI] + r[PJ]
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r, dx * dx + dy * dy - s * s])

    def cons_jac(z):
        x, y, r = z[:N], z[N:2 * N], z[2 * N:]
        dx = x[PI] - x[PJ]
        dy = y[PI] - y[PJ]
        s = r[PI] + r[PJ]
        J = np.zeros((4 * N + M, 3 * N))
        idx = np.arange(N)
        J[idx, idx] = 1
        J[idx, 2 * N + idx] = -1
        J[N + idx, idx] = -1
        J[N + idx, 2 * N + idx] = -1
        J[2 * N + idx, N + idx] = 1
        J[2 * N + idx, 2 * N + idx] = -1
        J[3 * N + idx, N + idx] = -1
        J[3 * N + idx, 2 * N + idx] = -1
        rows = 4 * N + np.arange(M)
        J[rows, PI] = 2 * dx
        J[rows, PJ] = -2 * dx
        J[rows, N + PI] = 2 * dy
        J[rows, N + PJ] = -2 * dy
        J[rows, 2 * N + PI] = -2 * s
        J[rows, 2 * N + PJ] = -2 * s
        return J

    def obj_grad(z):
        g = np.zeros(3 * N)
        g[2 * N:] = -1.0
        return g

    z0 = np.concatenate([P0[:, 0], P0[:, 1], P0[:, 2]])
    bounds = [(0, 1)] * (2 * N) + [(0, 0.5)] * N
    try:
        res = minimize(lambda z: -np.sum(z[2 * N:]), z0, jac=obj_grad, method="SLSQP",
                       bounds=bounds,
                       constraints=[{"type": "ineq", "fun": cons, "jac": cons_jac}],
                       options={"maxiter": 300, "ftol": 1e-12})
    except Exception:
        return None
    z = res.x
    return _repair(np.column_stack([z[:N], z[N:2 * N]]), z[2 * N:])


def _grid():
    k = int(np.ceil(np.sqrt(N)))
    pts = [((i + .5) / k, (j + .5) / k) for i in range(k) for j in range(k)][:N]
    return np.array([(x, y, .5 / k) for x, y in pts])


def solve(time_limit, best_so_far):
    t0 = time.time()
    budget = min(0.3 * time_limit, 5.0)
    rng = np.random.default_rng(2024)

    best, best_score = None, -1.0

    def consider(P):
        nonlocal best, best_score
        if P is not None and _valid(P) and P[:, 2].sum() > best_score + 1e-12:
            best, best_score = P, P[:, 2].sum()
            return True
        return False

    if best_so_far is not None:
        try:
            consider(np.asarray(best_so_far, float))
        except Exception:
            pass

    if best is not None:
        consider(_slsqp(best))

    cur, cur_score = best, best_score
    last_gain, it = 0, 0

    # Simulated annealing over centers; radii come from the exact LP,
    # with periodic SLSQP polishing of promising configurations.
    T0, T1 = 0.02, 0.0005
    while True:
        el = time.time() - t0
        if el >= budget:
            break
        frac = el / budget
        T = T0 * (T1 / T0) ** frac
        it += 1

        if cur is None or rng.random() < 0.15:
            C = rng.uniform(0.05, 0.95, (N, 2))
        else:
            C = cur[:, :2].copy()
            v = rng.random()
            if v < 0.4:
                C[rng.integers(N)] = rng.uniform(0.05, 0.95, 2)
            elif v < 0.8:
                C[rng.integers(N)] += rng.normal(0, 0.08, 2)
            else:
                C += rng.normal(0, 0.02, (N, 2))
        C = np.clip(C, 0, 1)

        P = _lp_radii(C)
        if P is not None:
            s = P[:, 2].sum()
            if cur is None or s >= cur_score or rng.random() < np.exp((s - cur_score) / T):
                cur, cur_score = P, s

            if consider(P):
                last_gain = it

            if it % 20 == 0 or s > best_score - 0.005:
                Q = _slsqp(P)
                if Q is not None:
                    if consider(Q):
                        last_gain = it
                    Q2 = _lp_radii(Q[:, :2])
                    if consider(Q2):
                        last_gain = it

        # Restart from the incumbent after a long stall.
        if it - last_gain > 300 and best is not None:
            cur, cur_score = best, best_score
            last_gain = it

    if best is None or not _valid(best):
        return _grid()
    return best
